<?php
declare(strict_types=1);
require_once __DIR__ . '/../functions/helpers.php';
require_role('customer');
$id=(int)($_GET['id']??0);
$stmt=db()->prepare('SELECT o.*,u.name AS account_name,u.email FROM orders o INNER JOIN users u ON u.id=o.user_id WHERE o.id=? AND o.user_id=? LIMIT 1');$stmt->execute([$id,$_SESSION['user_id']]);$order=$stmt->fetch();
if(!$order){set_flash('error','Order not found.');redirect('customer/orders.php');}
$stmt=db()->prepare('SELECT product_name,unit_price,quantity,subtotal FROM order_items WHERE order_id=? ORDER BY id');$stmt->execute([$id]);$items=$stmt->fetchAll();$flash=get_flash();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Order #<?=intval($id)?> | Gonzaga's Apparel</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/auth.css"></head><body class="shop-page"><header class="mini-header"><a href="../index.php"><img src="../assets/images/logo-placeholder.svg" alt="Gonzaga's Apparel"></a><nav><a href="../index.php">HOME</a><a href="orders.php">ORDERS</a><a href="profile.php">PROFILE</a><form action="../logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button type="submit">LOG OUT</button></form></nav></header><main class="shop-shell"><div class="section-kicker">ORDER <span></span></div><h1>ORDER #<?=intval($id)?></h1><?php if($flash):?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><div class="order-meta"><span>STATUS <strong><?=e(strtoupper($order['status']))?></strong></span><span>PAYMENT <strong><?=e($order['payment_method']==='cod'?'CASH ON DELIVERY':'BANK TRANSFER')?></strong></span><span>DATE <strong><?=e($order['created_at'])?></strong></span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>PRICE</th><th>QTY</th><th>SUBTOTAL</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=money((float)$item['unit_price'])?></td><td><?=intval($item['quantity'])?></td><td><?=money((float)$item['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="order-total"><span>SUBTOTAL <?=money((float)$order['subtotal_amount'])?></span><span>SHIPPING <?=$order['shipping_fee']>0?money((float)$order['shipping_fee']):'FREE'?></span><strong>TOTAL <?=money((float)$order['total_amount'])?></strong></div><section class="address-card"><h2>SHIPPING TO</h2><p><strong><?=e($order['shipping_name'])?></strong><br><?=e($order['shipping_phone'])?><br><?=e($order['shipping_address1'])?><br><?=($order['shipping_address2']?e($order['shipping_address2']).'<br>':'')?><?=e($order['shipping_city'])?>, <?=e($order['shipping_province'])?> <?=e($order['shipping_postal_code'])?><br><?=e($order['shipping_country'])?></p><?php if($order['notes']):?><p><strong>Notes:</strong> <?=e($order['notes'])?></p><?php endif;?></section></main></body></html>
